const item = $input.item.json;
let segments = [];
try {
  segments = JSON.parse(item.icpSegmentsJson || '[]');
  if (!Array.isArray(segments) || segments.length === 0) throw new Error('empty');
} catch (e) {
  segments = [
    { segmentName: 'Value-Driven Generalist', weight: 0.5, description: 'Price-sensitive shopper who compares offers before buying', painPoints: ['Skeptical of urgency claims'] },
    { segmentName: 'Loyal Repeat Customer', weight: 0.5, description: 'Existing customer motivated by recognition and perks', painPoints: ['Promo fatigue from frequent emails'] }
  ];
}

// Normalize weights so they sum to 1
const totalWeight = segments.reduce((sum, s) => sum + (typeof s.weight === 'number' ? s.weight : 0), 0);
const normalizedSegments = segments.map((s, idx) => ({
  personaId: 'PERSONA-' + (idx + 1),
  segmentName: s.segmentName || ('Segment ' + (idx + 1)),
  weight: totalWeight > 0 ? Math.round((s.weight / totalWeight) * 1000) / 1000 : Math.round((1 / segments.length) * 1000) / 1000,
  description: s.description || '',
  painPoints: s.painPoints || []
}));

return {
  json: {
    ...item,
    personaPanel: normalizedSegments,
    panelSize: normalizedSegments.length
  }
};

