const item = $input.item.json;
let parsed = {};
let reactionsParsedSuccessfully = true;
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
  if (!Array.isArray(parsed.reactions) || parsed.reactions.length === 0) throw new Error('empty reactions');
} catch (e) {
  reactionsParsedSuccessfully = false;
  parsed = {
    panelReactionConfidence: 3,
    reactions: (item.personaPanel || []).map(p => ({
      personaId: p.personaId,
      segmentName: p.segmentName,
      personaReactionQuote: 'Auto-generated placeholder: could not parse AI persona reactions.',
      sentiment: 'Neutral',
      purchaseIntentScore: 5,
      clarityRating: 5,
      keyObjections: ['AI reaction parsing failed - treat as a placeholder, not a real signal'],
      standoutPhrase: '',
      wouldShareWithFriend: false
    }))
  };
}

return {
  json: {
    ...item,
    personaReactions: parsed.reactions,
    panelReactionConfidence: parsed.panelReactionConfidence,
    reactionCount: parsed.reactions.length,
    reactionsParsedSuccessfully
  }
};

const item = $input.item.json;
const reactions = item.personaReactions || [];
const panel = item.personaPanel || [];

const weightById = {};
panel.forEach(p => { weightById[p.personaId] = p.weight; });

const sentimentValueMap = { Positive: 100, Mixed: 50, Neutral: 40, Negative: 0 };

let weightedPurchaseIntent = 0;
let weightedClarity = 0;
let weightedSentimentScore = 0;
let weightedShareRate = 0;
let totalObjections = 0;
let totalWeightUsed = 0;
const objectionFrequency = {};

reactions.forEach(r => {
  const weight = weightById[r.personaId] || (reactions.length > 0 ? 1 / reactions.length : 0);
  totalWeightUsed += weight;
  weightedPurchaseIntent += (r.purchaseIntentScore || 0) * weight;
  weightedClarity += (r.clarityRating || 0) * weight;
  weightedSentimentScore += (sentimentValueMap[r.sentiment] !== undefined ? sentimentValueMap[r.sentiment] : 40) * weight;
  weightedShareRate += (r.wouldShareWithFriend ? 1 : 0) * weight;
  (r.keyObjections || []).forEach(obj => {
    totalObjections += 1;
    objectionFrequency[obj] = (objectionFrequency[obj] || 0) + 1;
  });
});

if (totalWeightUsed > 0) {
  weightedPurchaseIntent = weightedPurchaseIntent / totalWeightUsed;
  weightedClarity = weightedClarity / totalWeightUsed;
  weightedSentimentScore = weightedSentimentScore / totalWeightUsed;
  weightedShareRate = weightedShareRate / totalWeightUsed;
}

const objectionDensity = reactions.length > 0 ? Math.round((totalObjections / reactions.length) * 100) / 100 : 0;

const topObjections = Object.entries(objectionFrequency)
  .sort((a, b) => b[1] - a[1])
  .slice(0, 3)
  .map(([text, count]) => text + ' (mentioned by ' + count + ')');

const compositeAppealScore = Math.max(0, Math.min(100, Math.round(
  weightedPurchaseIntent * 10 * 0.35 +
  weightedClarity * 10 * 0.25 +
  weightedSentimentScore * 0.25 +
  weightedShareRate * 100 * 0.15 -
  objectionDensity * 5
)));

let readinessTier = 'Launch Ready';
if (compositeAppealScore < 35) readinessTier = 'Do Not Launch';
else if (compositeAppealScore < 55) readinessTier = 'Needs Revision';
else if (compositeAppealScore < 75) readinessTier = 'Minor Tweaks Needed';

return {
  json: {
    ...item,
    weightedPurchaseIntent: Math.round(weightedPurchaseIntent * 10) / 10,
    weightedClarity: Math.round(weightedClarity * 10) / 10,
    weightedSentimentScore: Math.round(weightedSentimentScore * 10) / 10,
    weightedShareRate: Math.round(weightedShareRate * 1000) / 1000,
    objectionDensity,
    topObjections,
    compositeAppealScore,
    readinessTier
  }
};

const item = $input.item.json;
let parsed = {};
try {
  const rawText = item.output || item.text || item.response || '{}';
  const clean = rawText.replace(/```json|```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    overallRecommendation: 'Revise Before Launch',
    executiveSummary: 'Auto-flagged: could not parse AI synthesis output, defaulting to a cautious Revise Before Launch recommendation.',
    topStrengths: [],
    topRisks: ['AI synthesis parsing failed - treat this recommendation as a placeholder pending manual review'],
    suggestedCopyChanges: [],
    segmentsToPrioritize: [],
    recommendationConfidence: 40
  };
}

const decidedAt = new Date().toISOString();

return {
  json: {
    ...item,
    ...parsed,
    decidedAt,
    reportSummaryRow: [
      item.campaignId || 'N/A',
      item.campaignName || '',
      item.campaignChannel || '',
      item.budgetAtStake || 0,
      item.panelSize || 0,
      item.compositeAppealScore || 0,
      item.readinessTier || '',
      item.weightedPurchaseIntent || 0,
      item.weightedClarity || 0,
      parsed.overallRecommendation || '',
      JSON.stringify(parsed.topRisks || []),
      decidedAt
    ]
  }
};

